var t=`0823-slaai`;var n=`world-0823`;var a=`SZ`;var s=`southern-africa`;var o=4;var r=20;var d={en:`Slaai`,ua:`Слаай`};var l={en:`Slaai is a Eswatini dish made with avocado, tomato, red onion, peanut butter. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Слаай, страва кухні країни Есватіні. Основні складники: авокадо, помідор, червона цибуля, арахісова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`avocado`,2,`pcs`],[`tomato`,300,`g`],[`red-onion`,120,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`peanut-butter`,55,`g`],[`lemon-juice`,35,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:3,i:[[`lettuce`,160,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`cilantro`,12,`g`]]}];var u={slug:t,id:n,country:`SZ`,region:s,servings:4,minutes:20,title:d,text:l,steps:g};export{a as country,u as default,n as id,r as minutes,s as region,o as servings,t as slug,g as steps,l as text,d as title};